INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140842, 'spa', 'enviar, despachar (Qal)', 'El significado básico Qal: ''enviar, despachar'' (701x) — enviar personas, mensajeros, regalos u objetos a un destino. El árabe أَرْسَلَ, el coreano 보내다, el suajili kutuma y el hindi भेजा convergen en movimiento dirigido y deliberado. Gn 8:7-12 (Noé enviando al cuervo y la paloma) y Gn 20:2 (Abraham enviando a Sara) son ejemplos paradigmáticos tempranos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140849, 'spa', 'extender, tender (la mano)', 'Qal con יָד como objeto: ''extender, tender la mano'' (40x). El árabe مَدَّ, el coreano 내밀다 y el suajili kunyoosha marcan una clara divergencia semántica respecto a ''enviar''. Gn 3:22 (''no sea que extienda su mano''), Gn 22:10 (Abraham extendiendo su mano hacia el cuchillo) y Éx 3:20 (''extenderé mi mano'') muestran este gesto de poder, violencia o determinación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140853, 'spa', 'enviar, comisionar (Piel)', 'El intensivo Piel ''enviar, despachar'' (63x) — comisión deliberada de mensajeros, delegaciones o comunicaciones con intención formal. El árabe أَرْسَلَ y el coreano 보내다 mantienen el mismo campo léxico que la acepción 1. La intensificación Piel implica a menudo envío formal o reiterado, como en Gn 26:27 (los filisteos despidiendo a Isaac) y Éx 8:32 (el Faraón despachando mensajeros repetidamente).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140888, 'spa', 'ser enviado (pasivo)', 'Voz pasiva (participio pasivo Qal o Pual): ''ser enviado, ser soltado'' (5x). El árabe مُرْسَلٌ, el coreano 보내지다 y el suajili kutumwa confirman la transformación pasiva. Gn 44:3 (''los hombres fueron despedidos''), Gn 49:21 (''Neftalí es cierva suelta'') y 1 R 14:6 (''soy enviado a ti'') muestran tanto despacho literal como liberación poética.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140896, 'spa', 'despedir, soltar (Piel)', 'Piel con significado de ''despedir, soltar, dejar ir, liberar'' (34x) — frecuentemente referido a repudiar a una esposa, liberar esclavos o soltar cautivos. El árabe أَطْلَقَ/صَرَفَ y el coreano 보내다 con dirección ''fuera'' captan la fuerza separativa. Gn 18:16 (Abraham despidiendo a los ángeles), Gn 31:27 (la queja de Labán) y el estribillo del Éxodo sobre la negativa del Faraón a ''dejar ir'' al pueblo lo ilustran.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140904, 'spa', 'prender fuego, incendiar', 'Un uso destructivo que significa ''prender fuego, enviar fuego a'' (2x). Jue 20:48 (los israelitas incendiando las ciudades benjaminitas) y Sal 74:7 (''han prendido fuego a tu santuario'') emplean שָׁלַח con אֵשׁ (''fuego'') como objeto, produciendo un sentido conflagratorio violento dentro del dominio espacial-geográfico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140996, 'spa', 'expulsar, echar fuera (Piel)', 'Piel con significado de ''expulsar, echar fuera, desterrar'', con connotación de fuerza (2x). El árabe أَخْرَجَ/طَرَدَ, el coreano 내보내다 y el suajili kufukuza marcan una compulsión más intensa que la simple despedida. Gn 3:23 — Dios expulsando a Adán del Jardín del Edén — es el arquetipo: no un envío cortés sino un destierro irreversible.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141025, 'spa', 'Enviar o despachar una persona, mensaje o decreto oficial', 'Enviar o despachar una persona, mensaje o decreto oficial. Es el verbo administrativo arameo estándar para transmitir correspondencia y mandatos. Esdras 4:11-18 lo usa repetidamente para el intercambio de cartas entre funcionarios provinciales y la corte persa; Daniel 3:2, 28 y 6:23 lo emplean para convocar oficiales y liberar personas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141028, 'spa', 'Extender o alargar la mano, una extensión especializada del significado básico d', 'Extender o alargar la mano, una extensión especializada del significado básico de ''enviar''. En Esdras 6:12, el rey Darío advierte que todo rey o pueblo que ''extienda'' su mano para alterar el decreto o destruir el templo de Jerusalén será derribado. El modismo יִשְׁלַח יַד (''enviar la mano'') es compartido con el hebreo bíblico, donde a menudo implica intención hostil o destructiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141033, 'spa', 'Arma, proyectil', 'Arma o proyectil usado en la guerra: jabalina, lanza o armamento en general. En la narracion de la reconstruccion de Nehemias, cada trabajador sostenia su arma mientras laboraba (Neh 4:17, 23), y 2 Cronicas 23:10 y 32:5 usan el plural para armas almacenadas. Joel 2:8 describe al ejercito de langostas cayendo sobre las armas sin ser detenido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141035, 'spa', 'Dardo, arma letal', 'Proyectil letal — dardo, jabalina o espada — asociado especificamente con la muerte violenta. Job 33:18 advierte sobre un alma que ''perece por el arma'', y Job 36:12 repite la misma asociacion fatal. Se distingue del sentido general de armamento por su contexto mortal, donde el instrumento es agente directo de destruccion.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141036, 'spa', 'Brotes, renuevos', 'Brotes, renuevos o ramas botanicas — lo que una planta ''envia''. Cantares 4:13 usa el plural constructo femenino shelakhayikh: ''tus renuevos son un paraiso de granados'', transformando la imagen marcial de algo lanzado hacia afuera en el tierno crecimiento de un jardin. El termino captura la vitalidad organica de lo que brota y se extiende.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141038, 'spa', 'Sala', 'El nombre personal שֶׁלַח (Sala), que designa al hijo de Arfaxad y padre de Heber en la genealogía semita. Sus nueve apariciones abarcan Génesis 10:24 (la Tabla de las Naciones y la línea semita), Génesis 11:12-15 (su nacimiento, paternidad de Heber y longevidad) y 1 Crónicas 1:18, 24. Su posición genealógica es significativa como eslabón entre Sem y Abraham.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141046, 'spa', 'Mesa — una mesa como pieza de mobiliario, ya sea una humilde estera en el suelo ', 'Mesa — una mesa como pieza de mobiliario, ya sea una humilde estera en el suelo (como sugiere el trasfondo etimológico), una mesa de banquete real (1 R 2:7; 2 S 9:7), la mesa sagrada de los panes de la proposición en el tabernáculo (Ex 25:23-30; Nm 4:7) o incluso mesas de ídolos que provocan los celos divinos (Is 65:11; Mal 1:7). Por extensión, la palabra adquiere fuerza metonímica: «mi mesa» significa «mi provisión y hospitalidad». El español mesa, el francés table y el alemán Tisch se corresponden de manera uniforme.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141065, 'spa', 'Dominar, senorear (Qal)', 'El sentido Qal de ejercer dominio, gobernar o ensenorearse de otros. Nehemias 5:15 reprende a los gobernadores anteriores que ''se ensenoreaban'' del pueblo; Ester 9:1 lo usa dos veces para la dramatica reversion donde los judios obtuvieron dominio sobre sus enemigos. Eclesiastes indaga la futilidad de tal dominio: uno domina a otro para su propio dano (8:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141066, 'spa', 'Facultar, dar autoridad (Hifil)', 'El sentido del Hifil (causativo): hacer que alguien domine, es decir, facultar u otorgar autoridad. Ambas apariciones surgen en la reflexion teologica de Eclesiastes sobre la soberania divina: Dios da riquezas pero puede no facultar a la persona para disfrutarlas (Ec 6:2), o bien concede ese disfrute como don (5:19). El matiz causativo subraya que toda autoridad se recibe, no se toma.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141073, 'spa', 'Gobernar, tener dominio (Qal)', 'Gobernar, tener poder o dominio en el tronco basico Qal. Abarca tanto el poder fisico bruto (el fuego sobre los tres jovenes en Dan 3:27, los leones apoderándose de los acusadores en Dan 6:24) como el ejercicio de gobierno politico (Dan 5:7, 5:16). La amplitud va desde la autoridad politica hasta el dominio fisico puro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141074, 'spa', 'Designar gobernante (Hifil)', 'El Hifil causativo: hacer que alguien gobierne, designar como gobernante, otorgar dominio a otro. Se usa exclusivamente de Nabucodonosor recibiendo autoridad divina y luego delegandola, como en Dan 2:38 donde Dios ''te ha hecho gobernar'' y Dan 2:48 donde el rey ''lo hizo gobernar'' sobre la provincia de Babilonia. El matiz causativo subraya la cadena de autoridad delegada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141078, 'spa', 'Escudo, broquel', 'Escudo o broquel defensivo, a veces ornamental y exhibido en muros o torres. David tomó שְׁלָטִים de oro de los siervos de Hadad-ezer (2 Sam 8:7 = 1 Cr 18:7), y Joiada distribuyó escudos del arsenal del Templo (2 Re 11:10 = 2 Cr 23:9). En Cantares 4:4 cuelgan junto a los מָגִנִּים, sugiriendo un tipo distinto de pieza defensiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141086, 'spa', 'Dominio soberano o autoridad de gobierno (שָׁלְטָן), sustantivo arameo limitado ', 'Dominio soberano o autoridad de gobierno (שָׁלְטָן), sustantivo arameo limitado al libro de Daniel. El término abarca tanto el gobierno político humano —el dominio arrebatado a las bestias derrotadas (Dn 7:6, 12)— como la soberanía eterna divina —el dominio que ''no será destruido'' (Dn 7:14, 27). Nabucodonosor lo usa para confesar la suprema autoridad de Dios sobre todos los reinos, y los santos del Altísimo reciben un dominio que permanece para siempre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141097, 'spa', 'Gobernante o señor', 'Persona con dominio o autoridad gobernante. José es identificado como «el gobernante de la tierra» en Génesis 42:6. Eclesiastés lo usa para gobernantes de una ciudad (7:19) y quienes ejercen poder (10:5), al tiempo que señala los límites del dominio humano: nadie gobierna sobre la muerte ni el viento (8:8). El término enfatiza la posesión y el ejercicio de control, ya sea gobernanza legítima o señorío despótico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141098, 'spa', 'Que gobierna, dominante', 'El sentido adjetival central: quien gobierna, ejerce dominio o detenta autoridad. Se usa predicativamente de Dios que gobierna sobre el reino de los hombres (Dn 4:17, 25, 29; 5:21) y de los cielos que dominan (Dn 4:23), y sustantivalmente para funcionarios humanos: gobernantes (Dn 2:10; 5:29) y un capitán (Dn 2:15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141102, 'spa', 'Permitido, autorizado', 'Extensión semántica de ''tener autoridad'' a ''tener el derecho o permiso'', produciendo el sentido impersonal ''está permitido, está autorizado''. Atestiguado una vez en Esdras 7:24, en el decreto de Artajerjes que prohíbe la imposición de tributo al personal del templo. Este uso refleja el paso del poder político a la autorización legal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141108, 'spa', 'Oficial militar, capitán', 'Oficial militar, capitán: un oficial militar de alto rango o ayudante real, originalmente el ''tercer hombre'' en un carro de guerra que servía como guerrero combatiente junto al conductor y el portaescudo. Las catorce ocurrencias abarcan desde los capitanes de los carros de Faraón ahogados en el Mar Rojo (Éx 14:7; 15:4) hasta el oficial anónimo en cuyo brazo se apoyaba el rey de Israel (2 R 7:2, 17, 19) y Bidcar, el ayudante de Jehú (2 R 9:25).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141111, 'spa', 'Los tres, tríada', 'Los tres, tríada: un grupo de tres guerreros o ''los tres'' como designación de élite, un sentido numeral que refleja la raíz שׁלשׁ (''tres''). En 2 Samuel 23:8 (paralelo 1 Cr 11:11), el Ketiv lee ''el tercero'' o ''los tres'', nombrando al círculo más íntimo de los valientes de David. La tradición textual oscila entre שָׁלִישׁ y שְׁלֹשִׁים, lo que genera ambigüedad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141115, 'spa', 'Treinta (lectura homográfica)', 'Treinta (lectura homográfica): el numeral ''treinta'', una forma plural homográfica o variante donde שָׁלִישִׁים se lee como número cardinal en vez del título de oficial. El único caso claro es Proverbios 22:20, donde el orador pregunta ''¿No te he escrito treinta dichos de consejo y conocimiento?'' — lectura apoyada por el Qeré y por el paralelo egipcio de los Treinta Capítulos de Amenemope.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141121, 'spa', 'tercero (ordinal)', 'El número ordinal «tercero», que indica posición en una secuencia. Se usa atributiva o predicativamente de días (Gn 1:13; Gn 22:4, «al tercer día»), años (1 R 18:1, «en el tercer año»), ríos (Gn 2:14, «el tercer río»), hijos y reyes. Con 80 apariciones, esta es la acepción abrumadoramente dominante. Español «el tercero/la tercera», francés «le troisième», alemán «der dritte».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141122, 'spa', 'tercera parte, un tercio', 'Sustantivo fraccional: «la tercera parte» o «un tercio», denotando una de tres porciones iguales. David dividió su ejército en tres partes (2 S 18:2); el acto-signo profético de Ezequiel quema, golpea y esparce tercios de su cabello (Ez 5:2, 12). Las ofrendas de Números 15 requieren «un tercio de un hin» de vino (Nm 15:6-7). Español «el tercio», francés «le tiers» y alemán «ein Drittel» distinguen esta acepción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141130, 'spa', 'de tres años', 'Uso atributivo que designa un animal «de tres años», presente en el topónimo o epíteto «Eglat-shelishiyá» (una novilla de tres años) en Isaías 15:5 y Jeremías 48:34, en oráculos contra Moab. La referencia cruzada del BDB con las especificaciones sacrificiales de Génesis 15:9 confirma esta función de marcación de edad. Una acepción especializada pero lexicográficamente distinta, con solo dos apariciones claras.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141133, 'spa', 'por tercera vez', 'Uso adverbial o temporal que significa «la tercera vez» o «por tercera vez», indicando el número de repeticiones de un evento. El joven Samuel es llamado «la tercera vez» (1 S 3:8); la espada golpea «por tercera vez» en Ezequiel 21:14. Español «por tercera vez», francés «la troisième fois» y alemán «zum dritten Mal» expresan esta iteración adverbial, distinguida del ordinal por modificar la ocurrencia más que la posición.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141134, 'spa', 'los tres, grupo triple', 'Acepción colectiva o de agrupación: «los tres» o un «grupo de tres», que aparece en un pasaje textualmente difícil (2 S 23:18) que involucra una variante ketiv/qeré relativa a los guerreros de David. El contexto trata de Abisai como jefe «de los tres» o «de los treinta», con el numeral funcionando como designación sustantivada de grupo. Una acepción rara y críticamente compleja con una sola atestación clara.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141138, 'spa', 'tercer piso', 'Término arquitectónico: «el tercer piso» o «de tres pisos», referido al tercer nivel de una estructura escalonada. En Ezequiel 42:3, las galerías del templo están dispuestas «en tercios», tres pisos de cámaras. Español «en los tres pisos» refleja el significado espacial-estructural. Un uso único dentro de este lema, especializado en la arquitectura del templo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141146, 'spa', 'arrojar, lanzar (Hifil)', 'La acepción central del Hifil: arrojar, echar o lanzar con fuerza un objeto o una persona hacia un lugar específico — al agua, a una fosa, al fuego, al suelo o contra una superficie. Este es el grupo dominante con 92 apariciones, abarcando a José echado en la cisterna (Gn 37:24), la vara de Moisés arrojada al suelo (Éx 4:3; 7:9-10), el ejército egipcio lanzado al mar (Éx 15:1) y Jezabel arrojada desde una ventana (2 R 9:33).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141149, 'spa', 'ser arrojado (Hofal)', 'El pasivo Hofal: ser echado, ser arrojado, ser lanzado — el sujeto es quien recibe la acción, no quien la ejecuta. Quince apariciones donde la voz pasiva señala indefensión (la víctima) o agencia divina (Dios como agente implícito). En el Salmo 22:10, el salmista dice «sobre ti fui echado desde el vientre», y en 1 Reyes 13:24-28 el cuerpo del profeta «fue arrojado» en el camino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141156, 'spa', 'derribar, abatir (Hifil)', 'Hifil con énfasis en el movimiento descendente forzado: derribar, precipitar desde una altura o posición, con connotación de violencia, juicio divino o catástrofe. Se distingue de la acepción 1 por la direccionalidad gravitacional y el contexto de castigo o destrucción. En el Salmo 102:10 Dios «me levantó y me arrojó»; en Jeremías 9:19 el pueblo es «derribado» de su morada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141159, 'spa', 'desechar, rechazar (Hifil)', 'Hifil metafórico: desechar, rechazar, descartar o abandonar, sin lanzamiento físico real, sino el acto moral o relacional de repudio. El salmista suplica «no me deseches de tu presencia» (Sal 51:11; 71:9); el Salmo 2:3 imagina a naciones rebeldes diciendo «echemos de nosotros sus ataduras»; y 2 Crónicas 7:20 advierte que Dios «desechará» al Israel desobediente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141199, 'spa', 'expulsar, echar fuera (Hifil)', 'Hifil con connotación de expulsión: echar fuera, desterrar de un lugar, territorio o dominio, enfatizando la remoción y el destierro más que la trayectoria física. Solo 2 apariciones (2 R 24:20; Jr 52:3), ambas describiendo la expulsión de Judá de la presencia de Dios mediante el exilio babilónico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141234, 'spa', 'Saquear o despojar activamente —arrebatar bienes, riquezas o botín de personas, ', 'Saquear o despojar activamente —arrebatar bienes, riquezas o botín de personas, ciudades o naciones por la fuerza. Se usa en formas finitas, infinitivos y participios del Qal. Isaías 10:6 comisiona a Asiria ''para tomar botín''; Ezequiel 38:12-13 describe el saqueo del ganado y bienes del Israel restaurado. El verbo transmite la violencia directa de la apropiación forzosa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141237, 'spa', 'Ser despojado o saqueado —la forma reflexivo-pasiva del Hitpael que denota la ex', 'Ser despojado o saqueado —la forma reflexivo-pasiva del Hitpael que denota la experiencia de ser saqueado en lugar de realizar el saqueo. En el Salmo 76:5, los guerreros valientes ''fueron despojados'' (אֶשְׁתּוֹלָלוּ) de su botín tras la reprensión de Dios. Isaías 59:15 describe al que se aparta del mal como ''haciéndose presa'' (מִשְׁתּוֹלֵל) —una poderosa imagen de vulnerabilidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141245, 'spa', 'Botín, despojo, presa — bienes, propiedades y personas tomados por la fuerza en ', 'Botín, despojo, presa — bienes, propiedades y personas tomados por la fuerza en la guerra: vestiduras, metales preciosos, ganado y cautivos (Gn 49:27; Dt 20:14; Jos 7:21; 1 S 30:20). A menudo emparejado con בַּז como cuasi-sinónimo. El nombre profético Maher-shalal-hash-baz (Is 8:1-3) eleva el sustantivo a símbolo escatológico. Todas las lenguas meta emplean un único término para botín de guerra: español botín, francés butin, alemán Beute.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141270, 'spa', 'pagar, retribuir', 'La acepción dominante del Piel: pago y retribución, que cubre casi dos tercios de las apariciones. Abarca tanto la retribución positiva (recompensa) como la negativa (castigo), como en Éxodo 21:34-36 donde los daños deben ser restituidos. Español «pagar», francés «payer» y alemán «vergelten» confirman la lectura transaccional. El árabe يُجَازِي capta la doble dirección del desquite.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141272, 'spa', 'cumplir votos', 'Uso especializado del Piel restringido al cumplimiento de votos (נֵדֶר) hechos a Dios. Español «cumplir», distinto de «pagar», marca el registro religioso. Pasajes clave incluyen el Salmo 22:25 («cumpliré mis votos delante de los que le temen») y Deuteronomio 23:21. El árabe أَوْفَى y el suajili -timiza apuntan a la realización performativa más que al pago monetario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141276, 'spa', 'ser retribuido', 'El pasivo Pual: ser retribuido o recompensado. Proverbios 11:31 («si el justo es retribuido en la tierra») y Proverbios 13:13 ilustran la contraparte pasiva de la acepción 1. El Salmo 65:1 lo usa para votos que son cumplidos (pasivo de la acepción 2), y Jeremías 18:20 para el mal pagado por bien.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141277, 'spa', 'estar completo, en paz', 'La acepción estativa del Qal: estar completo, terminado o en paz. Este es el fundamento intransitivo de la raíz, del cual derivan todas las conjugaciones causativas. Pasajes clave incluyen 1 Reyes 7:51 (la obra del templo fue completada) y Nehemías 6:15 (el muro fue terminado). Isaías 60:20 extiende esta acepción a los días de duelo «completados».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141278, 'spa', 'restituir, restaurar', 'La acepción de restitución y restauración: hacer íntegro de nuevo lo dañado en bienes o relaciones. Levítico 5-6 prescribe la restitución con un quinto añadido; Joel 2:25 promete que Dios restituirá lo que consumió la langosta; 1 Reyes 9:25 lo usa para completar una edificación. El hilo semántico es hacer entero lo que estaba roto o incompleto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141279, 'spa', 'llevar a término', 'El causativo Hifil: llevar a término o completar. Job 23:14 («él completará lo que ha determinado para mí») e Isaías 44:28 («diciendo de Jerusalén: será edificada») presentan a Dios como agente que lleva sus propósitos a plena realización. Isaías 38:12-13 extiende esta acepción a Dios poniendo fin a una vida. La morfología causativa proyecta la «completitud» de la raíz sobre un agente externo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141305, 'spa', 'hacer la paz', 'Una sola aparición en 2 Samuel 10:19 donde los reyes arameos «hicieron paz» con Israel tras la derrota militar. Todas las traducciones convergen: español «hicieron paz», francés «firent paix», alemán «machte Frieden». Esta acepción diplomática de «hacer la paz» es una extensión natural de la restauración de la integridad en una relación rota, y conecta directamente con el sustantivo שָׁלוֹם.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141340, 'spa', 'Hifil y Hofal', 'Hifil y Hofal: hacer paz, establecer un pacto de paz o que se haga la paz. Es el sentido dominante, abarcando contextos militares y políticos como Josué 10:1 y 11:19, donde ciudades cananeas hacen paz con Israel. Deuteronomio 20:12 presenta el caso negativo: una ciudad que no hace paz. El carácter de tratado o alianza se refleja claramente en el uso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141344, 'spa', 'Qal estativo y participial', 'Qal estativo y participial: estar en paz, hallarse en una relación pacífica de pacto. En Job 22:21, Elifaz insta a Job a ''reconciliarse con Dios'' y recibir bien; en Salmo 7:4, David habla de ''el que estaba en paz conmigo'', su aliado. El participio pasivo en 2 Samuel 20:19 describe a los ''pacíficos'' fieles de Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141347, 'spa', 'Hifil en sentido completivo', 'Hifil en sentido completivo: cumplir, realizar o llevar a término. Distinto de hacer paz, este sentido refleja el significado raíz de integridad o consumación. En Isaías 44:26, Dios ''cumple'' (יַשְׁלִים) la palabra de su siervo y completa el consejo de sus mensajeros.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141349, 'spa', 'Participio pasivo Pual', 'Participio pasivo Pual: consagrado, íntegro, aquel que ha sido hecho completo o perfecto. En Isaías 42:19, el siervo del Señor es llamado מְשֻׁלָּם —el ''perfecto'' o ''consagrado''. El debate académico sobre esta forma (algunos leen ''su gobernante'' siguiendo la LXX) subraya la riqueza interpretativa de este uso poco frecuente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141352, 'spa', 'Completar/terminar', 'El verbo aparece en tres contextos administrativo-teológicos. Esdras 5:16 reporta que el templo de Jerusalén ''ha estado siendo terminado'' desde la colocación de los cimientos (pasivo continuo). Esdras 7:19 ordena a Esdras ''entregar en su totalidad'' (imperativo Haphel) los utensilios sagrados delante de Dios—completar la transferencia asignada. Daniel 5:26 interpreta la escritura en la pared: Dios ''ha terminado'' (llevado a su fin) el reino de Belsasar, ejecutando el juicio divino mediante conclusión definitiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141353, 'spa', 'Saludo epistolar administrativo', 'Saludo epistolar estándar en documentos administrativos arameos. Esdras 5:7 abre una carta con el simple saludo ''¡Paz!'' (shalom). Daniel 3:31 y 6:26 lo amplían en proclamaciones reales: ''Que tu paz se multiplique en gran manera''—un deseo de prosperidad y seguridad integral para los súbditos. Aunque clasificado bajo el dominio ''Dificultad, Adversidad, Alivio,'' el término mismo es completamente positivo, representando salud, bienestar y florecimiento general.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141354, 'spa', 'Ofrenda(s) de paz — ofrenda sacrificial de bienestar o comunión (שְׁלָמִים) en l', 'Ofrenda(s) de paz — ofrenda sacrificial de bienestar o comunión (שְׁלָמִים) en la que la carne se compartía entre Dios, el sacerdote y el adorador, expresando gratitud, cumplimiento de voto o devoción voluntaria. Central en la legislación levítica (Lv 3:1-17; 7:11-21) y presente en momentos narrativos clave como Éxodo 32:6. Las dos traducciones de la LXX — εἰρηνική y σωτήριον — reflejan una larga discusión académica sobre su significado exacto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141378, 'spa', 'Completo, entero o perfecto en calidad, medida o devoción moral', 'Completo, entero o perfecto en calidad, medida o devoción moral. Abarca pesas y medidas honestas (Dt 25:15; Pr 11:1), piedras de altar sin labrar (Dt 27:6; Jos 8:31), una iniquidad plena/madura (Gn 15:16), lealtad indivisa hacia Dios (1 R 8:61; 2 Cr 16:9) y la ''recompensa completa'' de Rut (Rt 2:12). En español completo/íntegro y en francés achevé reflejan esta plenitud.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141385, 'spa', 'Sano, ileso, habiendo llegado o regresado en estado de bienestar físico', 'Sano, ileso, habiendo llegado o regresado en estado de bienestar físico. Génesis 33:18 relata que Jacob llegó שָׁלֵם a Siquem; la Vulgata lo traduce incolumis (ileso). El alemán wohlbehalten (sano y salvo) capta con precisión este sentido de seguridad personal tras un viaje o una prueba.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141388, 'spa', 'Pacífico, amistoso, bien dispuesto hacia otros', 'Pacífico, amistoso, bien dispuesto hacia otros. Cuando Hamor y Siquem aseguran a los hijos de Jacob que ''estos hombres son pacíficos con nosotros'' (Gn 34:21), שָׁלֵם describe intención social, no condición física. En español pacíficos marca este registro interpersonal, distinto tanto de la integridad como de la seguridad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141392, 'spa', 'Nombre propio', 'Nombre propio del padre de Booz (Rut 4:20-21), con variantes ortográficas Salmón/Salma. Aparece en la genealogía de David (1 Cr 2:11) y se asocia con la fundación de Belén (1 Cr 2:51, 54). Las variantes reflejan distintas tradiciones textuales. Como bisabuelo de David, Salma/Salmón forma parte de la genealogía mesiánica que conecta la línea de Judá, a través de la gentil Rut, con la realeza de Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141393, 'spa', 'Vestidura, manto exterior', 'Vestidura, manto exterior: una prenda exterior, envoltura o manto que sirve como ropa y cobertura — forma variante de שִׂמְלָה con significado idéntico. Se emplea en contextos legales como propiedad o prenda de garantía (Éx 22:8, 25; Dt 24:13), en narrativa como acto profético simbólico (1 R 11:29-30) y evidencia de la estratagema gabaonita (Jos 9:5, 13), y poéticamente de Dios vestido de luz (Sal 104:2). El milagro del desierto de vestiduras indestructibles (Dt 29:4; Neh 9:21) y el aroma de las prendas de la novia del Cantar (Cnt 4:11) completan su rango de uso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141409, 'spa', 'Salomón (nombre propio)', 'Nombre propio de Salomón hijo de David, rey de Israel, cuyo reinado representa el cenit de la monarquía unida. Derivado de la raíz sh-l-m («paz, integridad»), el nombre fue dado por David tras las turbulentas circunstancias de su nacimiento (2 S 12:24). Aparece con mayor densidad en 1 Reyes 1-11 y 2 Crónicas 1-9, cubriendo su unción, la construcción del templo, sus matrimonios diplomáticos y su sabiduría proverbial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141429, 'spa', 'Selomot (nombre masculino)', 'שְׁלֹמוֹת (Selomot), nombre propio masculino portado por figuras levíticas en las listas genealógicas y administrativas de 1 Crónicas 23-26. Este individuo (o individuos) sirvió en las funciones del templo; en particular, en 1 Cr 26:25-26 Selomot fue custodio de los tesoros consagrados. La LXX lo registra como Σαλωμωθ, preservando la terminación masculina más larga.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141430, 'spa', 'Selomit (variante femenina)', 'שְׁלֹמִית (Selomit), forma variante o femenina del nombre, que aparece en alternaciones Ketiv/Qeré con Selomot en 1 Crónicas y también designa a un hijo de Roboam (2 Cr 11:20) y a un jefe de familia postexílico (Esd 8:10). La terminación yod-tav marca la forma femenina o diminutiva. La LXX lo registra como Σαλωμιθ, distinguiéndolo de la forma más larga.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141437, 'spa', 'Nombre propio masculino', 'Nombre propio masculino que significa ''Dios es mi paz'' o ''amigo de Dios'', identificando al jefe tribal de Simeón durante la era del desierto. Las cinco apariciones se encuentran en Números (1:6; 2:12; 7:36, 41; 10:19) en contextos ceremoniales y administrativos. Las glosas transliteran uniformemente — español ''Selumiel'', inglés ''Shelumiel'' — confirmando su identidad estable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141438, 'spa', 'Selemías (nombre propio)', 'El nombre personal Selemías/Shelemyahu, nombre teofórico que significa ''YHWH ha retribuido'', identificando a varias figuras bíblicas: un portero levítico bajo David equiparado con Salum (1 Cr 26:14), múltiples individuos en la época de Jeremías incluyendo oficiales y acusadores del profeta (Jer 36:14, 26; 37:3, 13; 38:1), y figuras postexílicas en Esdras y Nehemías involucradas en la reforma de esposas extranjeras y la reconstrucción del muro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141443, 'spa', 'Nombre propio levítico', 'Nombre propio de múltiples levitas y un descendiente real, con formas Selomit/Selomot. Entre los portadores destacan levitas del servicio del templo (1 Cr 23:18; 26:28), una hija de Roboam (2 Cr 11:20) y un cabeza de familia postexílica (Esd 8:10). El nombre, derivado probablemente de שָׁלוֹם, sugiere «pacífico» o «íntegro». Su recurrencia en familias levíticas refleja la idoneidad de un nombre de paz para servidores del santuario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141450, 'spa', 'Sacar o desenvainar una espada u arma de su vaina; con diferencia el uso más fre', 'Sacar o desenvainar una espada u arma de su vaina; con diferencia el uso más frecuente. Los guerreros a menudo se cuentan como ''hombres que desenvainan espada'' (Jue 8:10; 20:2; 1 Cr 21:5). El ángel de Balaam se presenta con ''espada desenvainada en mano'' (Nm 22:23). En español desenvainadores de y el cognado acadio compartido šalāpu confirman el núcleo militar de este sentido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141458, 'spa', 'Arrancar o extraer algo incrustado en su lugar, como un arma de una herida (Jue ', 'Arrancar o extraer algo incrustado en su lugar, como un arma de una herida (Jue 3:22, donde la hoja de Ehud no puede extraerse del cuerpo de Eglón) o metafóricamente algo plantado que se arranca con facilidad (Sal 129:6). Este sentido enfatiza el desprendimiento de una posición fija, no el desenvainado de un estuche diseñado para ello.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141460, 'spa', 'Quitar o sacarse una sandalia como acto legal simbólico', 'Quitar o sacarse una sandalia como acto legal simbólico. En Rut 4:7-8 el pariente redentor se quita el zapato para ratificar su renuncia al derecho de redención, una costumbre que el narrador explica como ya arcaica. En español quitó y en francés il tira hors resaltan el carácter deliberado y ritual de este gesto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141464, 'spa', 'De tres años', 'Forma participial Pual que describe a un animal de tres años, indicando plena madurez para fines sacrificiales. Las tres ocurrencias aparecen en Gn 15:9, donde Dios instruye a Abraham a traer una becerra, una cabra y un carnero de tres años para la ceremonia de corte del pacto. Las traducciones al español ''de tres años'' y al árabe ''ثُلَاثِيَّةً'' expresan esta construcción de edad con claridad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141465, 'spa', 'Triple, de tres pisos', 'Sentido adjetival que indica algo dispuesto en tres capas, pisos o hebras, un triplicar estructural. En Ez 42:6, las cámaras del templo se describen como ''de tres pisos'', y en Ec 4:12 el célebre ''cordón triple no se rompe fácilmente'' emplea esta forma. El español ''de tres pisos'' y ''triple'' expresan la metáfora arquitectónica de manera natural.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141466, 'spa', 'Hacer la tercera vez', 'Sentido verbal Piel de realizar una acción por tercera vez, expresando repetición deliberada. En 1 R 18:34, Elías ordena al pueblo verter agua sobre la ofrenda del altar una tercera vez; el triple empapamiento intensifica dramáticamente el milagro del fuego celestial. El español ''haced por tercera vez'' refleja fielmente la estructura imperativa seguida de la narración del cumplimiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141467, 'spa', 'Dividir en tres partes', 'Sentido Piel de dividir un territorio u objeto en tres partes iguales, una acción administrativa práctica. En Dt 19:3, Moisés ordena a Israel dividir la tierra prometida en tres regiones para las ciudades de refugio, garantizando accesibilidad geográfica. El español ''dividirás en tres'' traduce este sentido de partición con precisión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141469, 'spa', 'Al tercer día', 'Uso temporal Piel referido al tercer día, marcando un punto ordinal en el tiempo. En 1 S 20:19, Jonatán indica a David que acuda a cierto lugar ''al tercer día'', una señal vinculada a su plan para la huida de David de Saúl. El español ''al tercer día'' conserva el sentido temporal ordinal con naturalidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141472, 'spa', 'Tercera generación', 'Los de la tercera generación — nietos o bisnietos, usado sustantivamente a partir de un adjetivo ordinal. En el Decálogo y pasajes del pacto (Éx 20:5; 34:7; Nm 14:18; Dt 5:9), aparece en la fórmula ''hasta la tercera y cuarta generación'', expresando el largo alcance de las consecuencias pactales. Gn 50:23 lo emplea con ternura para los bisnietos de José.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141475, 'spa', 'El adverbio temporal ''anteayer'' o ''hace tres días,'' que funciona casi exclusivam', 'El adverbio temporal ''anteayer'' o ''hace tres días,'' que funciona casi exclusivamente dentro del modismo temol shilshom, que significa ''anteriormente, previamente, en el pasado.'' Atestiguado con diversas preposiciones: ki-temol shilshom (''como antes,'' Gn 31:2, 5; 1 S 19:7), mi-temol shilshom (''desde antes,'' Éx 21:29; Dt 4:42; 19:4, 6), y gam-temol gam-shilshom (''ni ayer ni anteayer,'' Éx 4:10). El español ''anteayer'' preserva el sentido literal, mientras que el uso idiomático apunta siempre a una referencia temporal general de ''en tiempos pasados.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141480, 'spa', 'Una ocurrencia anómala aislada en Pr 22', 'Una ocurrencia anómala aislada en Pr 22:20 donde la lectura Ketiv shilshom aparece en un contexto sin relación temporal. Algunas traducciones lo vierten como ''previamente,'' pero las glosas en hindi, árabe y suajili sugieren ''treinta'' (sheloshim), señalando una posible confusión textual con el numeral. Muchos eruditos modernos enmiendan a shalishim (''cosas excelentes'' o ''treinta dichos'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141485, 'spa', 'Allí (adverbio locativo)', 'Adverbio locativo que indica un lugar previamente mencionado o contextualmente implícito, funcionando tanto como locativo estático (''allí'') como direccional (''allá''). Aparece por primera vez en Gn 2:8 (''allí puso al hombre'') y sirve como estructura espacial esencial en toda la narrativa y poesía bíblica. Sus 835 apariciones se distribuyen en tres grupos originales que convergen en un único sentido indivisible.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141493, 'spa', 'Nombre (designación)', 'La palabra por la cual se identifica y llama a una persona, lugar o cosa, abarcando nombres propios, topónimos, el Nombre divino y actos de imposición de nombre. Central en la teología del pacto cuando se aplica al Nombre de Dios (Éx 3:15; Dt 12:5). Las traducciones lo vierten uniformemente como nombre, nom, Name.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141517, 'spa', 'Fama / Renombre', 'Fama, reputación o renombre alcanzado mediante hazañas poderosas o posición distinguida. Los ''hombres de nombre'' en Gn 6:4 y Nm 16:2 son hombres de renombre legendario. El sentido se desplaza de la etiqueta al legado: שֵׁם deja de ser una mera designación para convertirse en la memoria perdurable de una persona o acción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141554, 'spa', 'Sem', 'Sem: el nombre propio del hijo primogénito de Noé, progenitor del linaje semítico. Bendecido por Noé en el oráculo de Génesis 9:26-27, mencionado en la narrativa del Diluvio (Gn 5:32; 6:10; 7:13) y figura prominente en la Tabla de las Naciones (Gn 10:21-31) y la genealogía que conecta a Noé con Abraham (Gn 11:10-26). También aparece en 1 Crónicas 1:4, 17, 24 en el mismo rol genealógico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141557, 'spa', 'Nombre (arameo)', 'Nombre de una persona o deidad que denota identidad, autoridad o poder invocado, usado exclusivamente en las porciones arameas de Esdras y Daniel. Uso administrativo: preguntar por los nombres de los constructores (Esd 5:4, 10) y profetizar «en el nombre de» Dios (Esd 5:1). Uso teológico: bendecir el nombre de Dios como adoración (Dn 2:20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141567, 'spa', 'Lado izquierdo, dirección — el sentido espacial primario, que cubre 46 de 54 apa', 'Lado izquierdo, dirección — el sentido espacial primario, que cubre 46 de 54 apariciones, indicando el lado izquierdo o la dirección hacia la izquierda. Aparece regularmente en merismo con יָמִין («derecha») en frases como «a la derecha o a la izquierda» (Gn 13:9; Nm 20:17; 2 S 2:19). Construcciones preposicionales con מִן, עַל y לְ especifican ubicación o movimiento en relación con el lado izquierdo de lugares, ejércitos o personas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141573, 'spa', 'Mano izquierda — identifica específicamente la mano izquierda como parte del cue', 'Mano izquierda — identifica específicamente la mano izquierda como parte del cuerpo, a menudo con sufijos posesivos. La mano izquierda de Jacob se coloca sobre la cabeza de Manasés en la bendición de manos cruzadas (Gn 48:13-14). Sansón agarra un pilar con su mano izquierda (Jue 16:29) y la Dama Sabiduría sostiene riquezas en su izquierda (Pr 3:16). El francés sa gauche y el español su izquierda marcan consistentemente el uso posesivo-corporal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141578, 'spa', 'Norte — una rara extensión geográfica donde «izquierda» denota el norte, siguien', 'Norte — una rara extensión geográfica donde «izquierda» denota el norte, siguiendo la convención del antiguo Cercano Oriente de orientarse mirando hacia el este. Job 23:9 dice que Dios actúa «a la izquierda» (es decir, en el norte), pero Job no puede percibirlo. Las glosas en inglés north y en español al norte confirman esta correspondencia direccional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141599, 'spa', 'Ir a la izquierda', 'Ir hacia la izquierda, girar en dirección izquierda — expresando elección direccional, siempre emparejado con ''ir a la derecha''. La oferta de Abraham a Lot (Gn 13:9) y la promesa de Isaías (30:21) lo emplean para giros literales y figurados. En 2 S 14:19, la mujer sabia de Tecoa lo usa figuradamente para desviarse del camino recto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141600, 'spa', 'Izquierdo, del lado izquierdo', 'Relativo al lado izquierdo, usado como adjetivo o sustantivo para indicar orientación espacial opuesta a la derecha (יְמָנִי). En Lv 14:15-16, 26-27, especifica la palma izquierda del sacerdote durante los ritos de purificación, donde se coloca aceite en la mano izquierda y se rocía con el dedo derecho. En las descripciones del templo (1 R 7:21; 2 Cr 3:17) identifica la columna izquierda. El español ''a la izquierda'' y ''el izquierdo'' capturan ambos usos con precisión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141605, 'spa', 'Ser destruido, perecer — el sentido pasivo Nifal', 'Ser destruido, perecer — el sentido pasivo Nifal: ser destruido, perecer o ser exterminado; la entidad sufre la aniquilación en vez de causarla. Las formas pasivas árabes y las construcciones reflexivas españolas (fuimos destruidos) distinguen claramente esta voz del Hifil. Prominente en las advertencias de maldición del pacto (Dt 4:26, «ciertamente seréis destruidos») y en relatos narrativos de ruina nacional (Gn 34:30, el temor de Jacob de ser destruido por los cananeos).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141606, 'spa', 'Destruir, exterminar — el sentido causativo Hifil', 'Destruir, exterminar — el sentido causativo Hifil: destruir activamente, aniquilar o exterminar a un pueblo, nación o entidad mediante acción deliberada. El agente — ya sea Dios, un rey o Israel — provoca la obliteración total. El español destruir y el francés détruire/exterminer confirman de manera uniforme un único significado central a lo largo de 69 apariciones. Pasajes clave incluyen Deuteronomio 2:22 (Dios destruyendo a los horeos) y 2 Reyes 21:3 (las reformas de Ezequías).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141671, 'spa', 'El sentido objetivo de desolacion fisica', 'El sentido objetivo de desolacion fisica: un lugar reducido a escombros y ruina. El Salmo 46:8 contempla las ''desolaciones'' cosmicas de Dios, e Isaias 5:9 profetiza que las casas quedaran ''desiertas''. Los oraculos de Jeremias despliegan frecuentemente este sentido en la construccion de lamed de resultado: ''hare de esta ciudad una desolacion'' (Jer 4:7; 51:29, 43).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141672, 'spa', 'El sentido subjetivo', 'El sentido subjetivo: algo que provoca horror y consternacion estupefacta en los espectadores. Deuteronomio 28:37 advierte que Israel sera ''objeto de horror'' entre los pueblos, y Jeremias 5:30 declara ''cosa espantosa ha sucedido en la tierra''. La formula maldita profetica empareja esto con ''silbido'' y ''reproche'' (Jer 18:16; 19:8; 25:9, 18), senalando comunidades que provocan un estremecimiento de pavor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141683, 'spa', 'Una unica ocurrencia verbal en Nifal (Zac 7', 'Una unica ocurrencia verbal en Nifal (Zac 7:14) donde la tierra ''quedo desolada'' tras los exiliados. A diferencia de los sentidos nominales que describen un estado o una reaccion emocional, este capta el proceso de volverse ruina -- la transicion de habitado a yermo. La construccion verbal-procesual lo distingue de los otros sentidos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141690, 'spa', 'Sama (nombre personal)', 'Nombre propio שַׁמָּה aplicado a varios individuos: (a) un jefe edomita, hijo de Reuel y nieto de Esaú (Gn 36:13, 17; 1 Cr 1:37); (b) el tercer hijo de Isaí y hermano de David (1 Sam 16:9; 17:13); y (c) guerreros entre los valientes de David (2 Sam 23:11, 25, 33). Las siete apariciones designan este nombre personal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141693, 'spa', 'Samuel (profeta y juez)', 'Nombre propio de שְׁמוּאֵל, portado principalmente por el profeta, sacerdote y último juez de Israel, hijo de Elcaná y Ana de la serranía de Efraín. Nombrado en conexión con שָׁאַל («pedir», 1 S 1:20), sirvió desde la infancia en el santuario de Siló y se convirtió en la figura pivotal de la transición de Israel hacia la monarquía, ungiendo tanto a Saúl como a David. Portadores menores incluyen un líder simeonita (Nm 34:20) y un levita (1 Cr 7:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141697, 'spa', 'Nombre propio masculino', 'Nombre propio masculino que significa ''oído, renombrado'', de la raíz שָׁמַע. Identifica a tres individuos: (1) un espía rubenita en el desierto (Nm 13:4), (2) un hijo de David nacido en Jerusalén (2 S 5:14 = 1 Cr 14:4), y (3) un levita postexílico (Neh 11:17; 12:18). Se translitea como ''Samúa'' o ''Shammua''; la LXX varía en sus formas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141698, 'spa', 'El sentido general de informe, noticia o nuevas — información que se escucha y c', 'El sentido general de informe, noticia o nuevas — información que se escucha y circula entre la gente, ya sea buena o mala, verificada o incierta. La nuera de Elí se desploma al recibir la noticia de la captura del arca (1 S 4:19), David recibe informes contradictorios sobre la revuelta de Absalón (2 S 13:30), y Jeremías advierte que rumor perseguirá a rumor en el año de la caída de Jerusalén (Jer 51:46).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141701, 'spa', 'Un mensaje profético o anuncio divinamente autorizado dirigido a un auditorio — ', 'Un mensaje profético o anuncio divinamente autorizado dirigido a un auditorio — שְׁמוּעָה elevada de simple rumor a proclamación. Isaías 53:1 pregunta ''¿Quién ha creído a nuestro mensaje?,'' donde el ''mensaje'' es la misión misma del Siervo. Isaías 28:9 y 28:19 usan שְׁמוּעָה para la enseñanza profética que debe ser comprendida, y Abdías 1:1 abre con ''hemos oído un mensaje del SEÑOR.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141714, 'spa', 'Fama o reputación — lo que se oye acerca de una persona, estableciendo su imagen', 'Fama o reputación — lo que se oye acerca de una persona, estableciendo su imagen pública. En Ezequiel 16:56, la hermana de Jerusalén, Sodoma, ''no era noticia en tus labios'' — es decir, la infamia de Sodoma ni siquiera merecía mención. Este sentido extiende שְׁמוּעָה de una noticia puntual a una percepción pública sostenida, con el matiz de renombre o notoriedad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141717, 'spa', 'Qal: alegrarse, gozarse', 'El Qal intransitivo básico: alegrarse, regocijarse — la acepción dominante con 123 apariciones en todas las formas verbales finitas (perfecto, imperfecto, imperativo, yusivo, cohortativo, consecutivo). Es la experiencia emocional nuclear de alegría en respuesta a los actos de Dios (Sal 16:9, «mi corazón se alegra»), en las fiestas (Dt 12:18, «te regocijarás delante de Yahvé»), en la victoria (1 S 11:15) y en la vida cotidiana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141725, 'spa', 'Piel: alegrar, causar gozo', 'El Piel causativo: alegrar, causar regocijo — 27 apariciones. Aquí el sujeto produce activamente gozo en otro: Dios alegra a su pueblo (Sal 86:4, «alegra el alma de tu siervo»), el vino alegra el corazón (Sal 104:15; Jue 9:13), un hijo sabio alegra a su padre (Pr 10:1). El causativo es interlingüísticamente distintivo: árabe فَرَّحَ (forma II intensivo-causativa), español «alegrar».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141742, 'spa', 'Qal inf.: regocijarse', 'El infinitivo constructo Qal con preposiciones: «alegrarse», «al alegrarse» — 5 apariciones usadas como complementos verbales o cláusulas temporales. En Eclesiastés 3:12, «no hay cosa mejor que alegrarse (lismōaḥ) y hacer el bien»; en Ezequiel 35:14, «cuando toda la tierra se alegre (bismo''aḥ)». El árabe عِنْدَ فَرَحِي y el suajili kufurahi emplean formas infinitivas dedicadas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141771, 'spa', 'Piel: hacer regocijar (enemigos)', 'Una sola aparición del Piel en el Salmo 89:42 (heb. 89:41), donde el contexto es Dios haciendo que los enemigos se regocijen sobre el rey ungido caído: «hiciste alegrar a todos sus adversarios». El pasaje se distingue porque Dios es el agente de una alegría hostil, una inversión teológica del patrón habitual del Piel donde Dios alegra a su propio pueblo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141789, 'spa', 'Adj.: los que se alegran', 'El adjetivo שָׂמֵחַ usado sustantivamente: «los que se alegran», «los gozosos» — 2 apariciones. En Job 3:22, quienes «se regocijan sobremanera» al hallar la tumba, y en Amós 6:13, quienes «se alegran por nada». El uso sustantivado con artículo crea una categoría de personas definidas por su estado emocional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141799, 'spa', 'Alegre, gozoso, contento', 'Alegre, gozoso, contento: el sentido adjetival que describe a una persona, grupo, corazón u ocasión en estado de alegría y gozo — el uso dominante con 15 ocurrencias. Deuteronomio 16:15 ordena a Israel estar ''ciertamente alegre'' en la Fiesta de los Tabernáculos. Proverbios 15:13 enseña que ''el corazón alegre hermosea el rostro''. Es una alegría siempre relacional y visible, que va más allá del sentimiento privado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141803, 'spa', 'El que se regocija (sustantival)', 'El que se regocija (sustantival): el uso sustantivado donde שָׂמֵחַ funciona como nombre que significa ''el que se alegra'' o ''los gozosos'', con 4 apariciones. En Proverbios 2:14 los malvados son ''los que se alegran de hacer el mal'', y en Isaías 24:7 ''cesa el regocijo de los alegres''. El cambio va de describir una cualidad a nombrar una clase de personas definidas por su gozo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141809, 'spa', 'Regocijarse (verbal)', 'Regocijarse (verbal): una única ocurrencia verbal donde la forma funciona como yusivo del verbo cognado שָׂמַח en lugar del adjetivo — ''alégrense'' o ''gócese''. En 1 Crónicas 16:31 el salmo de alabanza de David exclama ''alégrense los cielos y gócese la tierra''. Esta ocurrencia se relaciona más con la raíz verbal que con el adjetivo propiamente dicho.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141810, 'spa', 'Gozo, alegría, deleite — el sentido predominante de gozo, alegría y deleite, que', 'Gozo, alegría, deleite — el sentido predominante de gozo, alegría y deleite, que abarca el regocijo ante Dios, la celebración festiva, la felicidad por la buena fortuna y el culto sagrado. El español alegría y el alemán Freude traducen consistentemente este amplio sentido emocional y ceremonial. El pueblo grita con gran gozo en la unción de Salomón (1 R 1:40) e Israel recibe el mandato de servir al Señor «con alegría» (Dt 28:47; Sal 100:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141822, 'spa', 'Placer, regocijo (como aspiración) — placer o regocijo visto como una aspiración', 'Placer, regocijo (como aspiración) — placer o regocijo visto como una aspiración humana sujeta a evaluación, especialmente en la literatura sapiencial donde Qohélet examina שִׂמְחָה como filosofía de vida. «Dije de la risa: es locura; y del placer (שִׂמְחָה): ¿de qué sirve?» (Ec 2:2). También en Jeremías 15:16, donde las palabras de Dios se convierten en «gozo» para el profeta, pero un gozo profundamente personal, casi solitario. Este sentido lleva un matiz de evaluación crítica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141833, 'spa', 'Tropezar, resbalar', 'Tropezar, resbalar o perder el equilibrio, usado intransitivamente. En 2 S 6:6 y 1 Cr 13:9, los bueyes tropiezan (o ''dejan deslizar el arca''), provocando el fatídico gesto de Uza. El español ''tropezaron'' captura la repentina pérdida de control — un momento de inestabilidad física con consecuencias devastadoras.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141834, 'spa', 'Arrojar, tirar abajo', 'Arrojar o lanzar con fuerza desde una altura. La vívida triple aparición en 2 R 9:33 — la orden de Jehú y su ejecución — hace inolvidable este sentido: ''¡Tiradla! Y la tiraron.'' El español ''tiradla/la tiraron'' transmite el acto deliberado y violento de lanzar a Jezabel desde la ventana del palacio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141836, 'spa', 'Remitir, soltar deudas', 'Soltar, remitir o dejar en barbecho — el sentido legal técnico del año sabático. Éx 23:11 ordena a Israel dejar la tierra sin labrar, mientras que Dt 15:2-3 extiende esto a la remisión de deudas. El español ''remitirá'' y ''soltarás'' destacan la dimensión económica: los acreedores deben dejar caer sus reclamos. Jr 17:4 aplica la misma imagen a Israel soltando su herencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141842, 'spa', 'Ser arrojado (pasivo)', 'Ser arrojado o derribado, la forma pasiva Nifal. Sal 141:6 describe a los jueces malvados ''despeñados'' por riscos pedregosos. El español ''fueron despeñados'' transmite la recepción pasiva de una fuerza violenta, completando el arco semántico desde el lanzamiento activo hasta la caída pasiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141843, 'spa', 'Remisión de deudas', 'La cancelación prescrita o suspensión temporal de obligaciones de deuda al cierre de cada ciclo sabático de siete años. Las cinco apariciones se concentran en Deuteronomio (15:1-2, 9; 31:10), donde funciona como término legal técnico. No es perdón de pecados, sino remisión formal de reclamaciones financieras entre miembros del pacto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141844, 'spa', 'Samay (nombre propio)', 'Samay, nombre personal llevado por tres varones de la tribu de Judá. El español ''Samay'' transliterado preserva la forma del nombre. La glosa alemana ''mein Name'' refleja una etimología popular derivada de ''shem'' (nombre). El primer Samay es hijo de Onam en la línea de Jerameel (1 Cr 2:28, 32); el segundo desciende de Caleb a través de Requem (1 Cr 2:44-45); el tercero pertenece a un sub-clan judaíta por medio de Mered (1 Cr 4:17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141845, 'spa', 'Jefe de familia manasita', 'Nombre personal de un jefe de familia manasita. Números 26:32 enumera a Semida entre los clanes de Manasés contados en el censo del desierto. Josué 17:2 confirma que los semidaítas recibieron una porción de tierra en Canaán. 1 Crónicas 7:19 lo ubica en la estructura genealógica de los descendientes de Manasés. El nombre marca tanto a una persona como a su clan, típico de la organización tribal donde el nombre del ancestro designa al grupo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141848, 'spa', 'cielos / cielo', 'La acepción primaria: los cielos o el cielo como extensión visible sobre la tierra — la atmósfera donde vuelan las aves (Gn 1:20), se forman las nubes, cae la lluvia y brillan los astros (Gn 1:14-17). Este es el uso abrumadoramente dominante con 329 apariciones, traducido uniformemente en todas las lenguas: español «los cielos», francés «les cieux», alemán «der Himmel», árabe السَّمَاوَات.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141850, 'spa', 'en los cielos', 'Los cielos como dominio locativo — «en los cielos» (בַּשָּׁמַיִם) — marcando dónde algo existe u ocurre, especialmente la morada de Dios (Dt 4:39; 1 R 8:30). Francés «dans les cieux» y español «en los cielos» conservan la estructura preposicional. Este uso porta un fuerte peso teológico: los cielos no son meramente lo de arriba, sino el lugar desde el cual Dios ve, juzga y actúa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141851, 'spa', 'desde los cielos', 'Los cielos como origen — «desde los cielos» (מִן הַשָּׁמַיִם) — la fuente desde la cual Dios habla (Neh 9:13), envía lluvia, fuego (Gn 19:24), maná y liberación. Español «desde los cielos» y francés «du ciel» marcan esta función ablativa. Teológicamente rica: la intervención divina desciende característicamente desde este locus.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141852, 'spa', 'hacia los cielos', 'Los cielos como meta direccional — «hacia/a los cielos» — marcado por he directiva (הַשָּׁמַ֫יְמָה, Éx 9:8), lamed u otras partículas direccionales. Moisés arrojando hollín «hacia los cielos» (Éx 9:8) o la escalera de Jacob que alcanza «hasta los cielos» (Gn 28:12) ilustran esta acepción espacial-dinámica. Español «hacia los cielos» y alemán «gen Himmel» captan la fuerza direccional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141855, 'spa', 'cielos de (constructo)', 'Los cielos en estado constructo — שְׁמֵי הַשָּׁמַיִם («cielos de los cielos») y formas ligadas similares — expresando el ámbito cósmico superlativo que ni siquiera los cielos pueden contener (1 R 8:27; 2 Cr 2:6). Esta construcción intensificadora semítica carece de equivalente preciso en la mayoría de las lenguas meta; las traducciones recurren a la paráfrasis («los cielos más altos») o a la traducción literal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141865, 'spa', 'tus / sus cielos (poseído)', 'Los cielos con sufijos pronominales — «tus cielos» (שָׁמֶיךָ, Sal 8:3), «sus cielos» (שָׁמָיו, Dt 33:28) — expresando asociación personal o posesión. Cuando el salmista contempla «tus cielos, obra de tus dedos», el sufijo transforma la bóveda cósmica en una interpelación íntima a Dios. Solo 5 apariciones, pero cada una posee intensidad poética y teológica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141879, 'spa', 'El sustantivo arameo para ''cielos'' o ''firmamento'', siempre en el plural enfatico', 'El sustantivo arameo para ''cielos'' o ''firmamento'', siempre en el plural enfatico shamayya, que funciona tanto como la boveda celeste visible como el ambito de la autoridad divina. En Daniel designa el cielo fisico -- aves (2:38; 4:9, 18), rocio (4:12, 20, 22, 30; 5:21), vientos (7:2) y nubes (7:13) -- y simultaneamente la sede de la soberania divina: ''el cielo gobierna'' (4:23). La expresion compuesta elah shamayya (''Dios del cielo'', Dan 2:18, 19, 37, 44; Esd 5:11-12; 6:9-10; 7:12, 21, 23) es un titulo diplomatico-liturgico favorecido en el periodo persa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141884, 'spa', 'El ordinal ''octavo,'' usado predominantemente en la fórmula ritual ''al octavo día', 'El ordinal ''octavo,'' usado predominantemente en la fórmula ritual ''al octavo día'' para señalar la culminación de períodos de purificación y ritos de consagración. Rige la fecha de la circuncisión (Lv 12:3), el clímax de la ordenación sacerdotal cuando apareció el fuego divino (Lv 9:1), el paso final en la purificación de enfermedades cutáneas (Lv 14:10, 23) y la asamblea de clausura de la Fiesta de los Tabernáculos (Lv 23:36, 39; Nm 29:35; Neh 8:18; 2 Cr 7:9). También designa el octavo mes calendario (1 R 6:38; Zac 1:1) y la octava suerte sacerdotal en las listas de 1 Crónicas 24-25.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141885, 'spa', 'Término musical litúrgico', 'En 1 Crónicas 15:21 y los títulos de los Salmos 6 y 12, ''Seminit'' aparece como una dirección musical-litúrgica. La interpretación estándar sugiere ''según la octava'' (clave, modo u octava), pero esto es especulativo. El español ''la octava'' y el inglés ''the eighth'' preservan el término numérico sin resolver su significado musical. La frase distingue un grupo de músicos levíticos de aquellos que tocan ''sobre Alamot,'' creando algún tipo de arreglo vocal o instrumental complementario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141886, 'spa', 'Espinos, abrojos', 'Sustantivo colectivo para espinos, abrojos o zarzas, usado exclusivamente en Isaías como símbolo de desolación y juicio divino sobre tierra improductiva o rebelde. El canto de la viña de Is 5:6 advierte que שָׁמִיר וָשַׁיִת («abrojos y espinos») invadirán el viñedo. El mismo par reaparece en Is 7:23-25 y 27:4.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141887, 'spa', 'Diamante, pedernal', 'Piedra o mineral muy duro —diamante, esmeril o pedernal— usado metafóricamente para expresar extrema dureza e indelibilidad. En Jer 17:1, el pecado de Judá está inscrito «con punta de diamante» (בְּצִפֹּרֶן שָׁמִיר), enfatizando su permanencia. En Ez 3:9, Dios hace la frente del profeta «más dura que el pedernal» (כְּשָׁמִיר חָזָק מִצֹּר).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141893, 'spa', 'Nombre de dos ciudades', 'Nombre de lugar que denota dos ciudades separadas. Josué 15:48 enumera a Samir entre los asentamientos de la región montañosa de Judá. Jueces 10:1-2 lo identifica como la residencia de Tola en la región montañosa de Efraín, donde juzgó a Israel durante veintitrés años y fue sepultado. La evidencia interlingüística (''Shamir,'' ''Samir'') simplemente transliteran el nombre, como es apropiado para nombres propios. La distinción geográfica entre las dos ciudades del mismo nombre era clara para los lectores antiguos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141894, 'spa', 'Nombre propio levítico', 'Nombre propio masculino que designa a levitas. El primer portador aparece entre los músicos de segundo rango designados por David para la procesión del arca (1 Cr 15:18, 20; 16:5). Un segundo Semiramot figura en la misión de enseñanza de Josafat (2 Cr 17:8, donde el Ketiv lee שְׁמִרִימוֹת). La LXX lo translitea como Σαμειραμωθ.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141895, 'spa', 'Vestidura exterior, manto o capa que se envolvia alrededor del cuerpo como ropa ', 'Vestidura exterior, manto o capa que se envolvia alrededor del cuerpo como ropa cotidiana. Este es el sentido dominante en casi todas las ocurrencias, desde los hijos de Noe cubriendo a su padre con una simlah (Gn 9:23) hasta el mandato de cambiarse de vestiduras como senal de transicion (Gn 35:2; 41:14). La prenda tambien aparece en contextos legales sobre vestir al desnudo (Dt 10:18) y la prohibicion de usar ropa del sexo opuesto (Dt 22:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141898, 'spa', 'Un trozo de tela o envoltorio reutilizado para cargar, envolver o cubrir objetos', 'Un trozo de tela o envoltorio reutilizado para cargar, envolver o cubrir objetos en lugar de vestirse con el. En el Exodo, Israel envolvio sus artesas de amasar en sus semalot (Ex 12:34), los hombres de Gedeon extendieron una simlah para recoger pendientes (Jue 8:25), y David envolvio la espada de Goliat en un pano en Nob (1 Sam 21:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141918, 'spa', 'Rey edomita', 'Nombre propio de un rey edomita oriundo de Masreca que gobernó antes de la monarquía israelita (Gn 36:36-37; 1 Cr 1:47-48). Forma parte de la lista de reyes de Edom conservada en Génesis 36, que documenta la organización política de los descendientes de Esaú. Su etimología es incierta. Su inclusión en las Escrituras israelitas refleja el reconocimiento del desarrollo nacional paralelo de Edom, nación hermana descendiente de los hijos gemelos de Isaac.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141920, 'spa', 'Quedar espantado, horrorizarse — el sentido psicológico de quedar espantado, hor', 'Quedar espantado, horrorizarse — el sentido psicológico de quedar espantado, horrorizado o atónito: 23 apariciones donde el foco pasa de paisajes arruinados a mentes destrozadas. Jeremías 2:12 ordena a los cielos que «se espanten» ante la apostasía de Israel; Esdras se sentó «espantado» hasta la ofrenda vespertina (Esd 9:3-4). Las formas Qal, Hitpael e Hitpolel portan esta fuerza emocional. El árabe يَذْهَشُ («quedar atónito») y el coreano 놀라다 («asombrarse») precisan este matiz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141921, 'spa', 'Desolador, devastador — la forma participial agentiva usada sustantivamente como', 'Desolador, devastador — la forma participial agentiva usada sustantivamente como «desolador» o «devastador»: cinco apariciones concentradas en las visiones apocalípticas de Daniel. La «abominación desoladora» (Dn 9:27; 11:31; 12:11) y la pregunta sobre «la transgresión que causa desolación» (Dn 8:13) emplean el participio activo Poel o Polel como término escatológico técnico. El español desolador y el alemán Verwüster captan la fuerza agentiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141922, 'spa', 'Estar desolado, quedar yermo — el sentido estativo-intransitivo de estar desolad', 'Estar desolado, quedar yermo — el sentido estativo-intransitivo de estar desolado o quedar en ruinas: 36 apariciones que describen tierras, ciudades, santuarios y caminos en estado de ruina o abandono. Levítico 26:22 advierte que los caminos quedarán desolados; Isaías 49:8 promete que las heredades desoladas serán restauradas. El árabe khariba («estar arruinado») y el coreano 황폐한 («desolado») convergen en este significado físico-geográfico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141925, 'spa', 'Asolar, devastar — el sentido causativo Hifil de asolar o devastar', 'Asolar, devastar — el sentido causativo Hifil de asolar o devastar: 15 apariciones donde un agente activo trae ruina sobre un lugar o un pueblo. Dios devastará los lugares altos de Israel (Lv 26:31), asolará sus santuarios (Lv 26:31) y desolará la tierra de modo que los enemigos se asombren (Lv 26:32). El relato de la campaña moabita lo emplea para la devastación militar (Nm 21:30), y Job lamenta que Dios lo ha «asolado».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141932, 'spa', 'Desolación, estado de ruina — el uso nominal abstracto mediante el infinitivo co', 'Desolación, estado de ruina — el uso nominal abstracto mediante el infinitivo constructo Hofal que denota el estado o proceso de desolación en sí: cuatro apariciones, todas agrupadas en la teología del año sabático de Levítico 26:34-35, 43 y su eco en 2 Crónicas 36:21. La tierra «disfruta sus sábados» durante su desolación (beshammah), compensando el descanso que Israel le negó. El árabe الخراب («la ruina») y el coreano 황폐의 («de desolación») confirman el significado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141959, 'spa', 'Causar horror, espantar — el sentido causativo-psicológico de hacer que otros qu', 'Causar horror, espantar — el sentido causativo-psicológico de hacer que otros queden espantados o causar horror: tres apariciones raras donde el Hifil se aplica no a la devastación física sino al impacto emocional. Dios hará que las naciones queden espantadas ante el juicio de Israel (Ez 32:10), Ezequiel mismo se sienta atónito entre los exiliados (Ez 3:15) y los amigos de Job deberían «espantarse» y taparse la boca con las manos (Job 21:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141985, 'spa', 'Desolado, asolado', 'Describe una condición de desolación, ruina o abandono, ya sea aplicada a lugares (santuarios, tierras) o a personas desvalidas y aturdidas. En 2 Samuel 13:20, Tamar permanece ''desolada'' en casa de su hermano, una devastación personal. En Jeremías 12:11, la tierra yace desolada porque nadie la toma en serio. La evidencia multilingüe converge uniformemente: español desolada, francés désolation, alemán Verwüstung.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141990, 'spa', 'Desolación, asolamiento (estado abstracto)', 'Desolación, asolamiento (estado abstracto). El estado abstracto de devastación o ruina (52 veces), empleado predicativamente o en cláusulas de propósito a lo largo de los profetas. Lv 26:33 advierte que la tierra quedará convertida en שְׁמָמָה, e Is 6:11 contempla ciudades desoladas. Solo Ezequiel acumula más de 18 apariciones, a menudo emparejando el término con מְשַׁמָּה para intensificar el efecto (Ez 35:7). La convergencia de ''desolación'' en español, ''désolation'' en francés y ''Öde'' en alemán confirma un sentido unívoco.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (141994, 'spa', 'Lugar(es) desolado(s), ruinas', 'Lugar(es) desolado(s), ruinas. Lugares desolados concretos o ruinas (5 veces), generalmente en plural constructo, referidos a sitios específicamente devastados. Jeremías habla de las שִׁמְמוֹת de Babilonia como ruinas que jamás serán reconstruidas (Jer 51:26, 62), y Daniel ora con la mirada puesta en ''nuestras desolaciones'', los escombros visibles de Jerusalén (Dn 9:18). El plural español ''desolaciones'' señala el paso del sentido abstracto al concreto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142007, 'spa', 'Engordar, prosperar', 'Engordar, volverse prospero y complaciente: se aplica a Israel bajo la bendicion divina cuando cae en la arrogancia. Deuteronomio 32:15 combina el perfecto e imperfecto Qal para retratar a Jesurun engordando como una bestia y luego coceando contra Dios. Jeremias 5:28 extiende la imagen a los malvados que se vuelven lustrosos. En el Hifil, Isaias 6:10 emplea la misma raiz con sentido causativo: hacer insensible el corazon del pueblo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142008, 'spa', 'aceite (sustancia)', 'Aceite de oliva como sustancia física: la acepción dominante que cubre la casi totalidad de las apariciones — líquido prensado de las aceitunas, empleado para ungir reyes y sacerdotes (1 S 16:13), mezclarlo con ofrendas de cereal (Lv 2:1-2), alimentar lámparas (Éx 25:6) y cocinar. El producto es tan central en la vida israelita que שֶׁמֶן aparece en prácticamente todos los géneros de las Escrituras.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142014, 'spa', 'madera de olivo', 'En 1 Reyes 6:23, 31-33, שֶׁמֶן designa la madera del olivo, no su aceite: los querubines y puertas del santuario interior están tallados en עֵץ שֶׁמֶן (madera de árbol de aceite). Español «olivo», francés «olivier» e inglés «olive» traducen el árbol en vez de su producto. Esta acepción metonímica — nombrar el árbol por su producto más valioso — solo aparece en la descripción del templo de Salomón.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142020, 'spa', 'fertilidad, abundancia', 'Extensión figurada donde שֶׁמֶן denota abundancia exuberante en vez de un líquido literal. Isaías 5:1 describe una viña en un «cuerno de aceite», una ladera ricamente fértil. Isaías 25:6 promete un festín de «manjares grasos», duplicando שֶׁמֶן para énfasis. La carne del salmista «se consume sin grasa» (Sal 109:24), significando que su cuerpo ha perdido toda vitalidad. Español «fertilidad» y «manjares» captan estos matices.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142024, 'spa', 'ungüento, aceite perfumado', 'Ungüento perfumado o aceite cosmético: aceite aromático mezclado con especias para uso como cosmético de lujo o perfume personal. Cantar de los Cantares 1:3 elogia los «ungüentos» (שְׁמָנִים, plural) del amado como más dulces que cualquier fragancia, y 4:10 los compara con especias costosas. Amós 6:6 condena a los ociosos ricos que se ungen con «los mejores ungüentos». Español «ungüentos» distingue explícitamente esta acepción aromática del aceite culinario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142039, 'spa', 'Fértil, graso (tierra)', 'Gordura o fertilidad de la tierra, el suelo y los pastos — terreno rico, productivo y abundante en cosechas. El informe de los espías sobre Canaán (Nm 13:20), el recuerdo de Nehemías sobre la tierra prometida (Neh 9:25, 35), el asentamiento simeonita en Gedor (1 Cr 4:40) y la promesa de Isaías de pastos ricos (30:23) atestiguan este dominio agrícola.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142042, 'spa', 'Rico, suntuoso (alimento)', 'Riqueza o suntuosidad de alimentos y sustancias — lo grasoso, aceitoso o lujosamente abundante para comer. La bendición de Jacob sobre Aser — ''su alimento será rico'' (Gn 49:20) — es el ejemplo fundacional. Hab 1:16 lo usa para la porción ''grasa'' de los caldeos obtenida de sus conquistas. El español ''grasoso'' distingue este sentido culinario del agrícola.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142043, 'spa', 'Gordo, robusto (seres vivos)', 'Gordura física o robustez de criaturas vivientes — bien alimentadas, corpulentas y fuertes de cuerpo. Jue 3:29 describe a los diez mil moabitas caídos como hombres ''robustos'' de valor. Ez 34:16 lo emplea para las ovejas ''gordas'' que Dios cuidará. El español ''robusto'' captura el sentido de salud corporal vigorosa, más allá de la mera abundancia de alimento o suelo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142048, 'spa', 'ocho (número cardinal)', 'El número cardinal ocho, empleado para contar, medir y datar en textos narrativos, legales y genealógicos. Aparece en las fórmulas patriarcales de longevidad de Génesis 5 (p. ej., Gn 5:4, ''ochocientos años''), en compuestos como dieciocho, y en especificaciones de cantidad (1 S 17:12, ''ocho hijos''). La alternancia masculino/femenino sigue las reglas estándar de concordancia numérica del hebreo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142061, 'spa', 'El numeral cardinal ''ochenta'', forma plural indeclinable usado a lo largo de la ', 'El numeral cardinal ''ochenta'', forma plural indeclinable usado a lo largo de la Biblia hebrea en formulas de edad (Gn 5:25-26, 28; 16:16; 35:28; Ex 7:7; Sal 90:10), conteos militares y censales (2 Re 10:24; Jer 41:5; 2 Cr 26:17), calculos cronologicos (1 Re 6:1; Jue 3:30) y enumeraciones de personas o concubinas (Cnt 6:8; Esd 8:8; 1 Cr 15:9). Tipicamente modifica un sustantivo singular como shanah (''ano'') y se combina con otros numerales para formar cifras compuestas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142065, 'spa', 'Qal: oír, percibir', 'Percepción auditiva básica en el Qal: el oído recibe un sonido sin volición implícita. El árabe سَمِعَ y los cognados semíticos confirman este como el significado raíz no marcado. Dominante con 921 apariciones: Lamec dice ''oíd mi voz'' (Gn 4:23) y la recepción profética se describe como simplemente oír (Nm 12:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142074, 'spa', 'Qal: escuchar, prestar atención', 'Escucha volitiva y atenta: oír dirigido por la intención. Las formas imperativas portan esta fuerza: ''¡Oíd ahora, rebeldes!'' (Nm 20:10). El mandato de Balaam ''Levántate, Balac, y escucha'' (Nm 23:18) y la fórmula del Shemá (Dt 6:4) ejemplifican este sentido de atención deliberada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142121, 'spa', 'Nifal: ser oído (pasivo)', 'Pasivo Nifal: ser oído, hacerse audible sin agente especificado. La noticia de José ''se oyó en la casa de Faraón'' (Gn 45:16), ningún martillo ''se oyó en el templo'' durante la construcción (1 R 6:7), y la oración de Israel ''fue oída'' en el cielo (2 Cr 30:27).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142139, 'spa', 'Qal: obedecer, acatar', 'Obediencia y acatamiento: oír que resulta en acción conforme. El español emplea distintivamente obedecer en lugar de oír o escuchar, confirmando un sentido separado. Los hermanos de José confiesan ''no obedecimos'' (Gn 42:21-22) y la fórmula deuteronómica ''si obedeciereis a mi voz'' (Dt 26:14) convierte la obediencia en el resultado esperado de la escucha.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142142, 'spa', 'Hifil: hacer oír, proclamar', 'Causativo Hifil: hacer que alguien oiga, proclamar públicamente. Dios hizo oír a Israel en el Sinaí (Dt 4:10); los músicos levíticos ''hacían oír'' en el culto (1 Cr 15:16, 28). El español hacer oír y el francés faire entendre confirman la lectura causativa de esta forma verbal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142210, 'spa', 'Hifil: convocar, reunir', 'Dos apariciones (1 S 15:4; 23:8) donde Saúl ''convocó'' al pueblo, un uso especializado del Hifil con sentido de llamar a reunión o movilizar. El español convocó y el inglés summoned divergen de toda glosa relacionada con oír, sugiriendo una extensión militar-administrativa: hacer que el pueblo oiga la convocatoria y se congregue.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142226, 'spa', 'Qal: comprender, entender', 'Una única aparición en Gn 11:7, en el relato de la torre de Babel: ''que no entiendan el habla el uno del otro.'' Aquí שָׁמַע no significa simplemente oír sino comprender: la confusión de lenguas implica que oirán sonidos pero no captarán su significado. El alemán verstehen (''comprender'') confirma esta extensión cognitiva más allá de la mera percepción auditiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142284, 'spa', 'Oír, escuchar', 'Pe''al: oír, escuchar o percibir auditivamente. Se usa para oír instrumentos musicales como señal (Dn 3:5, 7, 10, 15), escuchar informes hablados (Dn 5:14, 16) y recibir noticias (Dn 6:15). Los contextos de Daniel 3 son particularmente vívidos, donde oír la orquesta activa la orden de postrarse ante la imagen. El español ''oír'' y ''oigáis'' transmiten la recepción auditiva directa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142289, 'spa', 'Obedecer, ser sumiso', 'Hitpael reflexivo-intensivo: mostrarse obediente, someterse a la autoridad. En Dn 7:27, todos los dominios ''obedecerán'' al pueblo del Altísimo — el oír internalizado como cumplimiento voluntario. El español ''obedecerán'' hace explícito el paso de la percepción a la sumisión. Este desarrollo semántico de ''oír'' a ''obedecer'' está profundamente arraigado en todas las lenguas semíticas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142292, 'spa', 'Nombre propio masculino', 'Nombre propio masculino que significa ''oido'' o ''informe'', portado por multiples individuos de las tribus de Juda, Ruben, Benjamin y la comunidad postexilica. El Sema judahita desciende de Caleb (1 Cr 2:43-44), mientras que el portador de Nehemias 8:4 figura como personaje publico junto a Esdras durante la lectura solemne de la Ley.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142294, 'spa', 'Fama, renombre, reputación', 'Fama, renombre, reputación: fama, renombre o reputación pública — lo que se dice y se conoce ampliamente sobre una persona o nación. Números 14:15 advierte que las naciones han oído la fama de Dios; 1 Reyes 10:1 registra a la reina de Sabá respondiendo a la fama de Salomón. Deuteronomio 2:25 promete que Dios esparcirá la reputación de Israel entre los pueblos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142295, 'spa', 'Informe, noticia, nueva', 'Informe, noticia, nueva: un informe, una noticia o un relato transmitido a alguien — información concreta sobre sucesos o personas. Génesis 29:13 lo emplea para Labán al oír la noticia de la llegada de Jacob; Éxodo 23:1 prohíbe difundir un informe falso; Isaías 23:5 describe la angustia cuando el informe sobre Tiro llega a Egipto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142297, 'spa', 'Acto de oír, al oír', 'Acto de oír, al oír: el acto o la facultad de escuchar en sí, o el momento de percibir algo por el oído. En Job 42:5 — ''de oídas te había oído'' — el término denota la percepción auditiva más que un contenido. Salmo 18:44 lo usa con preposición para significar ''al oír'', es decir, tan pronto como escuchan. Este sentido abstracto aparece con preposiciones que destacan el aspecto temporal o instrumental de la audición.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142308, 'spa', 'Fama o informe', 'Informe o fama que se propaga acerca de los hechos o el poder de alguien. La fama de Josué recorrió la tierra tras Jericó (Jos 6:27); los gabaonitas vinieron por la fama de YHWH (Jos 9:9). La fama de Mardoqueo se extendió por las provincias (Est 9:4). En Jeremías 6:24 se refiere a un informe alarmante que causa temor. El término capta tanto la difusión de noticias como la reputación que resulta de ellas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142311, 'spa', 'Nombre propio masculino', 'Nombre propio masculino que funciona como variante de Sama/Simeah, enraizado en שׁמע (''oir''). El hermano de David aparece bajo esta forma en 1 Cronicas 2:13 y 20:7 (Qere), mientras que el Ketiv lee שמעי. Un hijo de David tambien porta el nombre (1 Cr 3:5, equivalente a Samua). Dos levitas en 1 Cronicas 6:30 y 39 completan las atestiguaciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142312, 'spa', 'Hermano de David', 'Nombre personal del hermano mayor de David y varios otros israelitas. 2 Samuel 13:3, 32 identifican a Simea como el hermano de David y padre de Jonadab (el Ketiv lee ''Simei,'' pero el Qere corrige a ''Simea''). 2 Samuel 21:21 nuevamente lo nombra como hermano de David, padre de Jonatán quien mató a un gigante filisteo. El nombre marca una línea familiar que se conecta hacia atrás con Isaí y hacia adelante a través de los sobrinos de David que se convirtieron en guerreros.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142314, 'spa', 'El nombre Shimon, derivado de shama (''oir''), que designa al segundo hijo de Jaco', 'El nombre Shimon, derivado de shama (''oir''), que designa al segundo hijo de Jacob (Gn 29:33), la tribu descendiente de el y su territorio absorbido por Juda (Jos 19:1-9). A menudo emparejado con Levi en reprension por la masacre de Siquem (Gn 34:25; 49:5-7). La Septuaginta lo traduce como Sumeon, preservando la etimologia. Lea declaro al nacer: ''Porque YHWH ha oido que soy aborrecida, me ha dado tambien este hijo''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142320, 'spa', 'El nombre Shimi/Shimei, llevado por unos diez individuos distintos', 'El nombre Shimi/Shimei, llevado por unos diez individuos distintos. El mas destacado es Simei hijo de Gera, cuya maldicion contra David (2 Sam 16:5-13) y ejecucion bajo Salomon (1 Re 2:36-46) forman un arco narrativo memorable. Otros portadores incluyen a un levita gersonita (Ex 6:17), uno de los administradores de David (1 Cr 27:27) y un ancestro de Mardoqueo (Est 2:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142330, 'spa', 'El nombre propio masculino Shema''yah/Shema''yahu (''Yahweh ha oido''), que identifi', 'El nombre propio masculino Shema''yah/Shema''yahu (''Yahweh ha oido''), que identifica al menos quince individuos distintos en el registro biblico. Los mas significativos teologicamente son el profeta que transmitio la palabra de Dios a Roboam contra la guerra civil (1 Re 12:22; 2 Cr 11:2) y el falso profeta de Nehelam a quien Jeremias denuncio (Jer 29:24-32). El resto son entradas genealogicas en Cronicas, Esdras y Nehemias.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142338, 'spa', 'Gentilicio tribal', 'Adjetivo gentilicio que significa «de la tribu de Simeón», usado para identificar a sus descendientes. Aparece en listas censales (Nm 26:14), contextos de liderazgo tribal (1 Cr 27:16), repartos territoriales (Jos 21:4) y para identificar individuos como Zimri (Nm 25:14). Designación tribal estándar dentro del sistema de las doce tribus, si bien el territorio de Simeón fue gradualmente absorbido por Judá.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142343, 'spa', 'Qal: guardar, observar (ley/pacto)', 'Tronco Qal: guardar, observar u obedecer mandamientos, estatutos, pactos y ordenanzas — la acepción dominante con casi 400 apariciones. Éxodo 12:17 (''guardaréis la fiesta de los panes sin levadura'') y Deuteronomio 5:12 (''guardarás el sábado'') muestran el verbo en el corazón de la obediencia al pacto. Las traducciones convergen: español guardar, francés garder, alemán bewahren/beachten.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142352, 'spa', 'Nifal: guardarse, precaverse', 'Tronco Nifal: guardarse, precaverse, tener cuidado — sentido reflexivo que advierte contra el peligro o la transgresión. Génesis 24:6 (''guárdate de llevar a mi hijo allá'') y Éxodo 19:12 (''guardaos de subir al monte'') enmarcan la autoprotección como respuesta a los límites divinos. La estructura reflexiva se explicita en español con cuídate/guárdate y en francés con garde-toi.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142368, 'spa', 'Qal: vigilar, acechar', 'Tronco Qal: vigilar, observar, acechar — enfatizando la vigilancia visual más que la custodia. El centinela apostado sobre una ciudad (2 S 11:16) y Elí observando los labios de Ana moverse en oración (1 S 1:12) resaltan la mirada del vigía. Las traducciones confirman la connotación de observación asignada: alemán der Wächter, español los guardas, los centinelas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142424, 'spa', 'Hitpael: guardarse a sí mismo', 'Tronco Hitpael reflexivo-intensivo: guardarse a sí mismo con esfuerzo deliberado. Solo tres apariciones — 2 Samuel 22:24 y Salmo 18:24 (la confesión paralela de David: ''me guardé de mi iniquidad'') y Miqueas 6:16 — pero cada una transmite una autodisciplina intensificada que supera la simple cautela del Nifal. La reduplicación reflexiva señala vigilancia moral como práctica sostenida y costosa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142445, 'spa', 'Qal/Nifal pasivo: ser guardado', 'Participio pasivo Qal y Nifal pasivo: ser guardado, custodiado o preservado por otro. La porción reservada para Saúl (1 S 9:24, ''lo que ha sido guardado'') y la promesa de que el Señor preserva a los fieles (Sal 37:28) expresan en voz pasiva la custodia protectora, divina o humana. El español fue guardado y el alemán bewahrte confirman el estado resultativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142465, 'spa', 'aferrarse a (ídolos vanos)', 'Sentido raro o disputado en Jonás 2:9: los que se aferran o veneran vanidades ilusorias. El español los que guardan y el inglés ''those who cling to'' sugieren un sentido transferido donde ''guardar'' cosas vacías se convierte en devoción mal encaminada — una inversión irónica del vocabulario pactual de la observancia fiel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142599, 'spa', 'Heces del vino', 'Heces o sedimento del vino -- el poso que se deposita cuando el vino envejece sin ser trasvasado, empleado en sentidos figurados tanto positivos como negativos. Positivamente, Isaias 25:6 usa dos veces el plural para describir el vino anejo mas fino del banquete escatologico de Dios. Negativamente, Jeremias 48:11 y Sofonias 1:12 despliegan la imagen para la complacencia imperturbada, mientras el Salmo 75:8 retrata las heces del juicio divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142600, 'spa', 'Nombre propio masculino', 'Nombre propio masculino que quizas significa ''guardian'' o ''vigilante'', relacionado con la raiz שׁמר. El portador mas significativo vendio a Omri la colina que se convirtio en Samaria (1 R 16:24, mencionado dos veces). Otros portadores incluyen un levita (1 Cr 6:46) y un aserita (1 Cr 7:34). La conexion del nombre con la capital de Israel le otorga una relevancia historica singular.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142605, 'spa', 'Hijo de Isacar', 'Nombre personal del hijo de Isacar y ancestro epónimo del clan simronita. Génesis 46:13 lista a Simrón entre los cuatro hijos de Isacar que vinieron a Egipto con Jacob. Números 26:24 registra a sus descendientes como uno de los clanes tribales de Isacar contados en el desierto. 1 Crónicas 7:1 repite la genealogía vinculando a Simrón con la línea de Isacar. El nombre funciona tanto personalmente (el hijo individual) como colectivamente (el clan).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142606, 'spa', 'Samaria (ciudad/región)', 'El nombre propio שֹׁמְרוֹן (Samaria), que designa la capital fortificada fundada por Omri sobre una colina comprada a Semer (1 R 16:24) y, por metonimia, el territorio del reino del norte. Central en las narrativas de la dinastía omrida, los profetas Elías y Eliseo, y la deportación asiria (2 R 17). Ezequiel la personifica como mujer infiel (Ez 23:4), subrayando su peso simbólico en la teología profética.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142619, 'spa', 'Nombre propio', 'Nombre propio de varios individuos bíblicos: un simeonita (1 Cr 4:37), el padre de uno de los héroes de David (1 Cr 11:45) y levitas dedicados al servicio del templo (1 Cr 26:10; 2 Cr 29:13). Posiblemente significa «vigilante» o «mi guardián», derivado de שָׁמַר (guardar). Su distribución entre diversas tribus y funciones muestra que era un nombre moderadamente difundido en Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142620, 'spa', 'Nombre teofórico', 'Nombre propio que significa «YHWH ha guardado/preservado», con variantes Semaryahu y Semarías. Lo llevaron un guerrero que se unió a David en Siclag (1 Cr 12:6), un hijo de Roboam (2 Cr 11:19) y dos hombres en tiempos de Esdras que habían tomado esposas extranjeras (Esd 10:32, 41). El nombre teofórico expresa confianza en la protección divina, reflejando la fe y gratitud de quienes así llamaron a sus hijos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142621, 'spa', 'Provincia persa de Samaria', 'Designación aramea para Samaria en documentos administrativos del período persa. Esdras 4:10 menciona funcionarios ''en Samaria'' (o ''en Shomrayin'') y el resto de la provincia de Trans-Éufrates. Esdras 4:17 dirige correspondencia a funcionarios samaritanos. El nombre funciona geográficamente para identificar la provincia del norte distinta de Judea. En este contexto administrativo, Samaria representa tanto la ciudad capital como el territorio provincial más amplio bajo el gobierno persa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142627, 'spa', 'sol (cuerpo celeste)', 'El sol en toda su amplitud semántica: luminaria física (Gn 37:9), marcador temporal para el amanecer y la puesta (Gn 15:12, 17; Jos 10:12-13), metáfora de gloria y justicia (Jue 5:31; Mal 3:20) y símbolo de la transitoriedad de la vida bajo su circuito (Eclesiastés passim). Todas las lenguas principales lo traducen con su término solar primario — el sol, le soleil, die Sonne — confirmando una equivalencia total.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142637, 'spa', 'almenas, pináculos', 'Ornamentos arquitectónicos descritos por el plural שִׁמְשׁוֹת en Isaías 54:12, dentro de la visión de la nueva Jerusalén cuyos portones son carbunclos y cuyos muros, piedras preciosas. El término probablemente designa escudos o almenas en forma de sol que coronan las murallas. El español almenas y el inglés ''battlements'' captan el sentido arquitectónico, mientras que el francés y el alemán conservan soleil/Sonne, reflejando la conexión etimológica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142641, 'spa', 'El nombre propio masculino שִׁמְשׁוֹן (Sansón), que identifica al juez-héroe dan', 'El nombre propio masculino שִׁמְשׁוֹן (Sansón), que identifica al juez-héroe danita cuyos enfrentamientos con los filisteos ocupan Jueces 13-16. Las 38 apariciones se concentran en estos cuatro capítulos, trazando su trayectoria desde su nacimiento milagroso (13:24), pasando por hazañas de fuerza sobrenatural (14:6, 19; 15:14-15; 16:3, 29-30), hasta su traición por Dalila y su muerte sacrificial (16:4-30). El nombre deriva de שֶׁמֶשׁ (''sol''), resonando con la geografía de su territorio natal cerca de Bet-semes (''casa del sol'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142643, 'spa', 'Escriba persa', 'Nombre propio de un escriba en la administración persa que se opuso a la reconstrucción de Jerusalén (Esd 4:8-23). Siempre aparece como «Simsai el escriba», en pareja con Rehum el comandante. El nombre es probablemente de origen persa o iranio, reflejo de la naturaleza multicultural de la burocracia persa. Simsai representa la oposición oficial al proyecto de restauración judía mediante correspondencia y procedimientos legales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142646, 'spa', 'Diente, dientes (parte del cuerpo)', 'Diente, dientes (parte del cuerpo). Diente o dientes como parte del cuerpo, el sentido dominante con 40 apariciones, que abarca la dentadura humana y animal en contextos literales, jurídicos y figurados. La ley del talión repite שֵׁן תַּחַת שֵׁן (''diente por diente'') en tres códigos legales (Éx 21:24, Lv 24:20, Dt 19:21), y Éxodo 21:27 lo aplica en la práctica: si un amo derriba el diente de su esclavo, el esclavo queda libre. Los usos figurados son igualmente expresivos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142647, 'spa', 'Marfil (diente de elefante)', 'Marfil (diente de elefante). Marfil como material de lujo derivado de los colmillos de elefante, con 10 apariciones concentradas en la literatura regia y profética. El gran trono de Salomón estaba recubierto de שֵׁן (1 R 10:18; 2 Cr 9:17), Acab construyó una ''casa de marfil'' (1 R 22:39), y los palacios del Salmo 45:8 exhalan mirra desde ''palacios de marfil''. Amós 3:15 y 6:4 denuncian el marfil como símbolo de riqueza abusiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142655, 'spa', 'Peñasco, risco puntiagudo', 'Peñasco, risco puntiagudo. Peñasco, risco o ''diente de roca'', con 4 apariciones que describen formaciones rocosas escarpadas. La más vívida es la narración del paso de Micmas en 1 Samuel 14:4-5, donde Jonatán y su escudero cruzan entre dos riscos con forma de שֵׁן llamados Boses y Sene, ''uno al norte frente a Micmas y el otro al sur frente a Geba''. Job 39:28 sitúa al águila en el שֵׁן de un precipicio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142663, 'spa', 'Tenedor, púa', 'Tenedor, púa. Tenedor o instrumento con puntas, en una sola aparición en 1 Samuel 2:13, donde los criados de los sacerdotes venían con un מַזְלֵג de tres puntas (''tenedor'') mientras la carne hervía. El שֵׁן aquí designa la púa o diente del tenedor: ''tres dientes'' (שְׁלֹשׁ הַשִּׁנַּיִם) describe la forma del utensilio. El español ''los dientes'' conserva la metáfora anatómica aplicada al instrumento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142675, 'spa', 'Dientes de bestias apocalípticas', 'Dientes de bestias aterradoras en las visiones apocalípticas de Daniel, cognado arameo del hebreo שֵׁן. Daniel 7:5 describe a la bestia-oso con huesos entre sus dientes, mientras que 7:7 y 7:19 retratan los dientes de hierro de la espantosa cuarta bestia que devora y aplasta. Las traducciones españolas ''dientes de ella'' e inglesas ''its teeth'' reflejan correctamente las formas con sufijo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142677, 'spa', 'Qal: odiar, aborrecer', 'El sentido finito central del Qal: sentir odio, animosidad o aversión moral hacia una persona, cosa o práctica. Cubre formas de perfecto, imperfecto, imperativo y consecutivo. La evidencia multilingüe es notablemente uniforme: español aborrezco/odio, francés haïr, alemán hassen, árabe يَكْرَهُ, todos convergen en hostilidad emocional visceral. Se usa tanto del odio interpersonal (Gn 37:4) como de la repulsión divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142679, 'spa', 'Qal ptcp.: enemigo, odiador', 'El participio activo Qal funciona como sustantivo: ''el que odia, enemigo, adversario''. Es una de las principales palabras hebreas para designar al enemigo personal, y aparece constantemente con sufijos pronominales: שֹׂנְאַי ''los que me odian'' (Éx 20:5; Sal 69:5). En Éxodo 18:21 describe la cualidad que los líderes deben poseer: שֹׂנְאֵי בָצַע, ''los que aborrecen la ganancia deshonesta''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142683, 'spa', 'Qal inf.: odiar, el odio', 'El infinitivo constructo y absoluto Qal, usado como complemento verbal (''comenzó a odiar'', Gn 37:5, 8) o nominalmente como el concepto abstracto de odio. En Jueces 15:2, שָׂנֹא שְׂנֵאתָהּ (''ciertamente la odiaste'') emplea el infinitivo absoluto para la intensificación enfática. En 2 Samuel 19:7 Joab acusa a David de ''amar a los que te odian y odiar a los que te aman'', donde el infinitivo funciona como sustantivo abstracto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142686, 'spa', 'Qal ptcp. pas.: aborrecida', 'El participio pasivo Qal que describe el estado de ser odiada o desamada, con función adjetival. Su contexto más memorable es la ''esposa aborrecida'' en la ley matrimonial patriarcal (Gn 29:31, 33; Dt 21:15-16), donde Lea es שְׂנוּאָה — no necesariamente despreciada sino emocionalmente desfavorecida en comparación con Raquel. Proverbios 30:23 extiende la imagen a la mujer aborrecida que consigue casarse.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142690, 'spa', 'Piel ptcp.: odiador intenso', 'El participio intensivo Piel, que designa a quienes odian con fuerza o persistencia amplificada. Se distingue de la acepción 2 por el tronco intensivo Piel y aparece en poesía elevada y contextos teofánicos: el grito de batalla de Moisés ''huyan los que te odian'' (Nm 10:35), el Cántico de Moisés (Dt 32:41) y la acción de gracias de David (2 S 22:41). El árabe المُبْغِضِين (Forma IV intensiva) confirma la intensificación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142703, 'spa', 'pasivo proverbial: ser odiado', 'Par residual de apariciones en Proverbios (14:17, 14:20) donde la forma funciona dentro de sentencias sapienciales sobre las consecuencias sociales de la necedad y la pobreza: ''el hombre de malas maquinaciones es odiado'' y ''el pobre es odiado aun de su prójimo''. Estos usos estativo-pasivos en el discurso proverbial describen el rechazo social como resultado natural, entre el odio activo de la acepción 1 y la desaprobación conyugal de la acepción 4.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142773, 'spa', 'Cambiar, transformar', 'El verbo describe alteración o transformación visible. 2 Reyes 25:29 reporta que Joaquín ''cambió sus vestiduras de prisión'' cuando fue liberado para cenar con el rey babilónico (o posiblemente su rostro/apariencia cambió). Eclesiastés 8:1 observa que la sabiduría ''cambia'' el rostro de una persona—transforma su semblante. Lamentaciones 4:1 lamenta cómo ''el oro ha cambiado''—perdió su brillo o se empa. El verbo captura transformación física o visible desde un estado a otro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142774, 'spa', 'El sentido dinámico intransitivo — experimentar un cambio o ser alterado — apare', 'El sentido dinámico intransitivo — experimentar un cambio o ser alterado — aparece vívidamente cuando el rostro de Belsasar cambia de color ante la escritura en la pared (Dn 5:6, 9) y cuando el semblante de Nabucodonosor se altera de furia (Dn 3:19). Las vestiduras de Sadrac, Mesac y Abed-nego no fueron alteradas por el fuego (Dn 3:27). El español ''se alteró'' capta la cualidad involuntaria y reflexiva de este cambio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142775, 'spa', 'El sentido estativo — ser diferente o diverso — se concentra en la visión de las', 'El sentido estativo — ser diferente o diverso — se concentra en la visión de las cuatro bestias de Daniel 7, donde cada reino ''es diferente de'' (מִן) los demás (Dn 7:3, 7, 19, 23, 24). No se trata de cambio a lo largo del tiempo sino de distinción inherente. La preposición מִן marca comparación, y el español ''diferente/diferentes'' confirma que es una cualidad de ser, no un proceso de transformación.');